import { Scene, MathShape3D, TracePath, Sphere, Math3D, Color, Vec3 } from "retiam";

const scene = new Scene({ canvas });

// 1. Manim-style semi-transparent 3D cube with illuminated edges
const mathBox = new MathShape3D(Math3D.createBox(4, 4, 4), {
    fill: Color.fromHex("#3b82f6"),
    fillOpacity: 0.6,
    transmission: 0.3,
    stroke: Color.WHITE,
    stroke_width: 0.06
});
scene.add(mathBox);

// 2. Moving particle tracer
const particle = new Sphere(0.3, { fill: Color.fromHex("#f43f5e") });
scene.add(particle);

// 3. Extruded motion ribbon following the particle
const ribbon = new TracePath({
    target: particle,
    maxAge: 2000,
    smoothing: 2,
    tapering: true,
    stroke: Color.fromHex("#fbbf24"),
    stroke_width: 0.15
});
scene.add(ribbon);

// Animate orbital motion
scene.always(({ time }) => {
    particle.transform.position = new Vec3(
        Math.cos(time * 2.0) * 5.0,
        Math.sin(time * 3.0) * 2.0,
        Math.sin(time * 2.0) * 5.0
    );
});
